const raw = $input.first().json;
const rows = Array.isArray(raw) ? raw : (raw && Object.keys(raw).length ? [raw] : []);
const porUser = {};
for (const r of rows) { (porUser[r.user_id] = porUser[r.user_id] || []).push(r); }
const AHORA = Date.now();
const out = [];
for (const uid of Object.keys(porUser)) {
  const hist = porUser[uid].sort((a,b) => new Date(b.created_at) - new Date(a.created_at));
  const cur = hist[0], prev = hist[1];
  if (!cur || cur.porcentaje_apertura_asignado == null) continue;
  const reciente = (AHORA - new Date(cur.created_at).getTime()) < 35*60*1000;
  const esReasignacion = cur.porcentaje_apertura_asignado !== cur.porcentaje_apertura_deseado;
  const cambio = !prev || prev.porcentaje_apertura_asignado !== cur.porcentaje_apertura_asignado;
  if (reciente && esReasignacion && cambio) out.push({ json: cur });
}
return out;

const chats = $input.all();
const reasig = $('Filtrar reasignados').all().map(i => i.json);
const out = [];
for (let k = 0; k < chats.length; k++) {
  const prev = chats[k].json;
  const fila = Array.isArray(prev) ? prev[0] : (prev && Object.keys(prev).length ? prev : null);
  if (!fila || !fila.chat_id) continue;
  const r = reasig[k];
  const subiendo = r.porcentaje_apertura_asignado > r.porcentaje_apertura_deseado;
  const text = '\uD83D\uDCA7 Reasignacion de agua en tu cuenca\n\n'
    + 'El agente ' + (subiendo ? 'subio' : 'ajusto') + ' la apertura de tu valvula de '
    + r.porcentaje_apertura_deseado + '% a ' + r.porcentaje_apertura_asignado + '%.\n\n'
    + (r.motivo_asignacion || '');
  out.push({ json: { body: JSON.stringify({ chat_id: fila.chat_id, text }) } });
}
return out;
